#!/bin/bash
set -euo pipefail

# Test: .claude/hooks/memory-refresh.sh — UserPromptSubmit hook for memory
# auto-refresh in long-lived sessions.
# Generated by /qa on 2026-04-16

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$SCRIPT_DIR/.claude/hooks/memory-refresh.sh"
SETTINGS="$SCRIPT_DIR/.claude/settings.json"

PASS=0
FAIL=0
pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; return 0; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; return 0; }

echo "Testing: memory-refresh hook"
echo

# ── File existence + shebang ──────────────────────────────────────

[ -f "$HOOK" ] && pass "memory-refresh.sh exists" || fail "memory-refresh.sh missing"
[ -x "$HOOK" ] && pass "memory-refresh.sh is executable" || fail "memory-refresh.sh not executable"
head -1 "$HOOK" | grep -q '^#!/bin/bash' && pass "bash shebang" || fail "bad shebang"

# ── bash 3.2 syntax ───────────────────────────────────────────────

/bin/bash -n "$HOOK" 2>/dev/null \
  && pass "bash 3.2 syntax clean" \
  || fail "bash -n rejects the script"

# ── Portability guards ────────────────────────────────────────────

# Look for actual readlink invocation (skip matches in comments)
! grep -qE '^[[:space:]]*[A-Za-z_]+=.*readlink -f|^[[:space:]]*readlink -f' "$HOOK" \
  && pass "no readlink -f invocation (GNU-only)" \
  || fail "uses readlink -f"

grep -q 'stat -f %m' "$HOOK" && grep -q 'stat -c %Y' "$HOOK" \
  && pass "handles both BSD and GNU stat" \
  || fail "stat flag incompatibility — mtime check breaks on one OS"

! grep -q '…' "$HOOK" \
  && pass "no Unicode ellipsis (bash 3.2 parser safety)" \
  || fail "Unicode ellipsis present"

# ── Hook contract: must always exit 0 ─────────────────────────────

# Even with no memory symlink, no git repo, nothing — must not error.
TMPDIR="/tmp/mem-refresh-test.$$"
mkdir -p "$TMPDIR"
CLAUDE_PROJECT_DIR="$TMPDIR" /bin/bash "$HOOK" >/dev/null 2>&1 \
  && pass "exits 0 when no memory symlink exists" \
  || fail "errors on missing memory — would break session prompts"

# With a symlink to a non-git dir
ln -s "$TMPDIR" "$TMPDIR/memory"
CLAUDE_PROJECT_DIR="$TMPDIR" /bin/bash "$HOOK" >/dev/null 2>&1 \
  && pass "exits 0 when memory isn't a git repo" \
  || fail "errors on non-git memory"

rm -rf "$TMPDIR"

# ── Throttle logic ────────────────────────────────────────────────

grep -q 'AGE.*300' "$HOOK" || grep -q '\-lt 300' "$HOOK" \
  && pass "throttle set to 5 minutes (300s)" \
  || fail "no throttle — hook would thrash on every prompt"

grep -q 'FETCH_HEAD' "$HOOK" \
  && pass "throttle uses FETCH_HEAD mtime (cheap, no git command)" \
  || fail "throttle doesn't use FETCH_HEAD — slower path"

# ── Background + non-blocking ─────────────────────────────────────

grep -qE '\) &' "$HOOK" \
  && pass "fetch runs in background (doesn't block prompt)" \
  || fail "fetch is synchronous — adds latency to every prompt"

grep -q 'disown' "$HOOK" \
  && pass "disowns background job (survives shell exit)" \
  || fail "no disown — background job could be killed early"

# ── Safety: fast-forward only ─────────────────────────────────────

grep -q -- '--ff-only' "$HOOK" \
  && pass "pull is --ff-only (never merges or rebases memory)" \
  || fail "pull allows merges — risks conflicted memory state"

# ── Registered in settings.json ───────────────────────────────────

[ -f "$SETTINGS" ] && pass "settings.json exists" || fail "settings.json missing"

jq . "$SETTINGS" >/dev/null 2>&1 \
  && pass "settings.json is valid JSON" \
  || fail "settings.json has invalid JSON"

jq -e '.hooks.UserPromptSubmit' "$SETTINGS" >/dev/null 2>&1 \
  && pass "UserPromptSubmit hook array present" \
  || fail "no UserPromptSubmit hook array"

jq -e '.hooks.UserPromptSubmit[].hooks[].command | select(contains("memory-refresh.sh"))' "$SETTINGS" >/dev/null 2>&1 \
  && pass "memory-refresh.sh wired into UserPromptSubmit" \
  || fail "hook not registered in settings.json"

# ── Summary ───────────────────────────────────────────────────────

echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
